/* LearnForge — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #ffffff;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.12);
  --transition: 0.25s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
}

/* ── NAV ─────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 0 2rem;
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 68px;
  gap: 2rem;
}

.nav-logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--black);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}

.nav-logo span {
  display: inline-block;
  width: 28px;
  height: 28px;
  background: var(--lime);
  border-radius: 6px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  list-style: none;
  flex: 1;
}

.nav-links a {
  display: block;
  padding: 0.5rem 0.85rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-700);
  text-decoration: none;
  border-radius: 8px;
  transition: background var(--transition), color var(--transition);
}

.nav-links a:hover,
.nav-links a.active { background: var(--gray-100); color: var(--black); }

.nav-cta {
  display: inline-flex;
  align-items: center;
  padding: 0.6rem 1.4rem;
  background: var(--black);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
  text-decoration: none;
  border-radius: 50px;
  white-space: nowrap;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}

.nav-cta:hover { background: var(--burgundy); transform: translateY(-1px); }

.nav-mobile-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  color: var(--gray-700);
}

/* ── HERO ─────────────────────────────────────────── */
.hero {
  padding: 5rem 2rem 4rem;
  text-align: center;
  background: linear-gradient(160deg, #fafafa 0%, #f5f5f5 100%);
  overflow: hidden;
}

.hero-inner { max-width: 900px; margin: 0 auto; }

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.1;
  color: var(--black);
  margin-bottom: 1.25rem;
  letter-spacing: -0.02em;
}

.hero h1 .accent { color: var(--burgundy); }

.hero p {
  font-size: 1.15rem;
  color: var(--gray-600);
  max-width: 640px;
  margin: 0 auto 2rem;
}

.hero-btns {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  padding: 0.85rem 2rem;
  background: var(--black);
  color: var(--white);
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  border-radius: 50px;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary:hover { background: var(--burgundy); transform: translateY(-2px); }

.btn-secondary {
  display: inline-flex;
  align-items: center;
  padding: 0.85rem 2rem;
  background: transparent;
  color: var(--black);
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  border-radius: 50px;
  border: 2px solid var(--black);
  transition: background var(--transition), color var(--transition), transform var(--transition);
}

.btn-secondary:hover { background: var(--black); color: var(--white); transform: translateY(-2px); }

/* Hero Tabs */
.hero-tabs {
  display: inline-flex;
  background: var(--white);
  border-radius: 50px;
  padding: 4px;
  box-shadow: var(--shadow);
  margin-bottom: 1.5rem;
}

.hero-tab-btn {
  padding: 0.5rem 1.5rem;
  border: none;
  background: none;
  border-radius: 50px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  color: var(--gray-600);
  transition: background var(--transition), color var(--transition);
}

.hero-tab-btn.active { background: var(--black); color: var(--white); }

.hero-preview {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  max-width: 820px;
  margin: 0 auto;
  border: 1px solid var(--gray-200);
}

.hero-preview-panel {
  display: none;
  background: var(--white);
  padding: 2rem;
}

.hero-preview-panel.active { display: block; }

.preview-mockup {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 1.5rem 2rem;
  text-align: left;
}

.preview-mockup-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.mockup-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--gray-200);
}

.mockup-dot:first-child { background: #ff5f57; }
.mockup-dot:nth-child(2) { background: #febc2e; }
.mockup-dot:nth-child(3) { background: #28c840; }

.preview-mockup-url {
  flex: 1;
  background: var(--white);
  border-radius: 6px;
  padding: 0.3rem 0.75rem;
  font-size: 0.8rem;
  color: var(--gray-400);
  border: 1px solid var(--gray-200);
}

.preview-grid {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 1rem;
  min-height: 220px;
}

.preview-sidebar {
  background: var(--black);
  border-radius: var(--radius);
  padding: 1rem;
  color: var(--white);
}

.preview-sidebar-item {
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

.preview-sidebar-item.active { background: var(--lime); color: var(--black); }

.preview-main-content {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.preview-stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.preview-stat-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1rem;
  border: 1px solid var(--gray-200);
  text-align: center;
}

.preview-stat-card .stat-num {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--black);
}

.preview-stat-card .stat-label {
  font-size: 0.7rem;
  color: var(--gray-600);
}

.preview-chart {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1rem;
  border: 1px solid var(--gray-200);
  height: 100px;
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
}

.bar-chart-bar {
  flex: 1;
  border-radius: 4px 4px 0 0;
  background: var(--lime);
  opacity: 0.8;
}

.preview-course-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1rem;
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.course-thumb {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  background: var(--lime);
  flex-shrink: 0;
}

.course-info { flex: 1; }
.course-title { font-size: 0.85rem; font-weight: 700; color: var(--black); }
.course-meta { font-size: 0.75rem; color: var(--gray-600); }

.progress-bar-wrap {
  background: var(--gray-200);
  border-radius: 4px;
  height: 6px;
  margin-top: 0.4rem;
}

.progress-bar-fill {
  height: 100%;
  border-radius: 4px;
  background: var(--lime);
}

/* ── STATS BAR ────────────────────────────────────── */
.stats-bar {
  background: var(--black);
  padding: 2.5rem 2rem;
}

.stats-bar-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
}

.stat-item { text-align: center; }

.stat-num {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--lime);
  line-height: 1;
  display: block;
}

.stat-label {
  font-size: 0.9rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.25rem;
}

.stat-divider {
  width: 1px;
  height: 50px;
  background: rgba(255,255,255,0.15);
}

/* ── SECTION COMMONS ─────────────────────────────── */
.section { padding: 5rem 2rem; }
.section-alt { background: var(--gray-50); }

.section-inner { max-width: 1200px; margin: 0 auto; }

.section-label {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 0.3rem 0.9rem;
  border-radius: 50px;
  margin-bottom: 1rem;
}

.section-title {
  font-size: clamp(1.8rem, 3.5vw, 2.75rem);
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.05rem;
  color: var(--gray-600);
  max-width: 600px;
}

.section-header { margin-bottom: 3rem; }
.section-header.centered { text-align: center; }
.section-header.centered .section-subtitle { margin: 0 auto; }

/* ── CARDS ────────────────────────────────────────── */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-200);
  transition: transform var(--transition), box-shadow var(--transition);
}

.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.4rem;
}

.card h3 { font-size: 1.15rem; font-weight: 700; color: var(--black); margin-bottom: 0.5rem; }
.card p { font-size: 0.92rem; color: var(--gray-600); }

/* 3-col grid */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; }

/* ── PRODUCTS SECTION ────────────────────────────── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.product-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem 1.5rem;
  border: 2px solid var(--gray-200);
  text-decoration: none;
  color: inherit;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  border-color: var(--black);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-card-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.product-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--black);
  margin-bottom: 0.5rem;
}

.product-card p {
  font-size: 0.88rem;
  color: var(--gray-600);
  flex: 1;
}

.product-card-link {
  margin-top: 1.25rem;
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--burgundy);
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

/* ── WHY CHOOSE US TABS ───────────────────────────── */
.why-tabs {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
  border-bottom: 2px solid var(--gray-200);
  padding-bottom: 0;
}

.why-tab-btn {
  padding: 0.75rem 1.25rem;
  border: none;
  background: none;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  color: var(--gray-600);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: color var(--transition), border-color var(--transition);
}

.why-tab-btn:hover { color: var(--black); }
.why-tab-btn.active { color: var(--black); border-bottom-color: var(--lime); }

.why-tab-panel { display: none; }
.why-tab-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 2.5rem; align-items: center; }

.why-features-list { list-style: none; display: flex; flex-direction: column; gap: 0.75rem; }

.why-features-list li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.95rem;
  color: var(--gray-700);
}

.why-features-list li::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--lime);
  flex-shrink: 0;
}

.why-visual {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  border: 2px dashed var(--gray-200);
}

/* ── TESTIMONIALS CAROUSEL ────────────────────────── */
.carousel-wrap { position: relative; overflow: hidden; }

.carousel-track {
  display: flex;
  transition: transform 0.4s ease;
}

.testimonial-card {
  min-width: 380px;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-200);
  margin-right: 1.5rem;
  flex-shrink: 0;
}

.testimonial-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  background: var(--lime);
  color: var(--black);
  padding: 0.2rem 0.7rem;
  border-radius: 50px;
  margin-bottom: 1rem;
}

.testimonial-quote {
  font-size: 1rem;
  color: var(--gray-700);
  font-style: italic;
  margin-bottom: 1.25rem;
  line-height: 1.65;
}

.testimonial-author { font-weight: 700; font-size: 0.9rem; color: var(--black); }
.testimonial-role { font-size: 0.82rem; color: var(--gray-400); }

.carousel-controls {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  background: var(--white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}

.carousel-btn:hover { background: var(--black); border-color: var(--black); color: var(--white); }

.carousel-dots { display: flex; gap: 0.4rem; }
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-200);
  cursor: pointer;
  transition: background var(--transition);
}
.carousel-dot.active { background: var(--black); }

/* ── PRICING ──────────────────────────────────────── */
.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 2px solid var(--gray-200);
  transition: border-color var(--transition), transform var(--transition);
}

.pricing-card.featured {
  border-color: var(--black);
  background: var(--black);
  color: var(--white);
  transform: scale(1.03);
}

.pricing-card:hover:not(.featured) { border-color: var(--black); transform: scale(1.02); }

.pricing-label {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1rem;
  color: var(--gray-600);
}

.pricing-card.featured .pricing-label { color: var(--lime); }

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--black);
  margin-bottom: 0.25rem;
}

.pricing-card.featured .pricing-price { color: var(--white); }
.pricing-card.featured .pricing-note { color: rgba(255,255,255,0.6); }
.pricing-note { font-size: 0.85rem; color: var(--gray-600); margin-bottom: 1.5rem; }

.pricing-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin-bottom: 1.75rem;
}

.pricing-features li {
  font-size: 0.88rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.pricing-features li::before {
  content: '✓';
  font-weight: 700;
  color: var(--lime);
  flex-shrink: 0;
}

.pricing-card.featured .pricing-features li { color: rgba(255,255,255,0.85); }

.pricing-cta {
  display: block;
  text-align: center;
  padding: 0.85rem;
  border-radius: 50px;
  font-weight: 700;
  font-size: 0.9rem;
  text-decoration: none;
  transition: background var(--transition), color var(--transition), transform var(--transition);
}

.pricing-card:not(.featured) .pricing-cta {
  background: var(--lime);
  color: var(--black);
}

.pricing-card:not(.featured) .pricing-cta:hover { background: var(--black); color: var(--white); transform: translateY(-1px); }

.pricing-card.featured .pricing-cta {
  background: var(--lime);
  color: var(--black);
}

.pricing-card.featured .pricing-cta:hover { background: var(--white); }

/* ── INTEGRATIONS ─────────────────────────────────── */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 1rem;
}

.integration-item {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1.25rem 1rem;
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: border-color var(--transition), transform var(--transition);
}

.integration-item:hover { border-color: var(--black); transform: translateY(-2px); }

.integration-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: var(--gray-100);
  margin: 0 auto 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
}

.integration-name { font-size: 0.78rem; font-weight: 600; color: var(--gray-700); }

/* ── FAQ ACCORDION ────────────────────────────────── */
.faq-list { display: flex; flex-direction: column; gap: 0.75rem; max-width: 760px; margin: 0 auto; }

.faq-item {
  background: var(--white);
  border-radius: var(--radius);
  border: 1px solid var(--gray-200);
  overflow: hidden;
  transition: border-color var(--transition);
}

.faq-item.open { border-color: var(--black); }

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  background: none;
  border: none;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--black);
  cursor: pointer;
  text-align: left;
  gap: 1rem;
}

.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
  transition: background var(--transition), transform var(--transition);
}

.faq-item.open .faq-icon { background: var(--lime); transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
  padding: 0 1.5rem;
}

.faq-item.open .faq-answer { max-height: 300px; padding: 0 1.5rem 1.25rem; }

.faq-answer p { font-size: 0.92rem; color: var(--gray-600); }

/* ── CTA BANNER ───────────────────────────────────── */
.cta-banner {
  background: var(--black);
  padding: 5rem 2rem;
  text-align: center;
}

.cta-banner h2 {
  font-size: clamp(1.8rem, 3.5vw, 2.75rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-banner p { font-size: 1.05rem; color: rgba(255,255,255,0.7); margin-bottom: 2rem; }

.cta-banner .btn-primary {
  background: var(--lime);
  color: var(--black);
  font-size: 1.05rem;
  padding: 1rem 2.5rem;
}

.cta-banner .btn-primary:hover { background: var(--white); }

/* ── FOOTER ───────────────────────────────────────── */
.footer {
  background: var(--gray-800);
  color: rgba(255,255,255,0.7);
  padding: 4rem 2rem 2rem;
}

.footer-inner { max-width: 1200px; margin: 0 auto; }

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand { }
.footer-logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--white);
  display: flex;
  align-items: center;
  gap: 0.4rem;
  text-decoration: none;
  margin-bottom: 0.75rem;
}

.footer-logo span {
  display: inline-block;
  width: 24px;
  height: 24px;
  background: var(--lime);
  border-radius: 5px;
}

.footer-tagline { font-size: 0.88rem; }

.footer-col h4 {
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  margin-bottom: 1rem;
}

.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }

.footer-col ul a {
  font-size: 0.88rem;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-col ul a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p { font-size: 0.82rem; }

/* ── TOOLS GRID ───────────────────────────────────── */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1.25rem;
}

.tools-category {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1.5rem;
  border: 1px solid var(--gray-200);
}

.tools-category h4 {
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--burgundy);
  margin-bottom: 0.75rem;
}

.tools-category ul { list-style: none; display: flex; flex-direction: column; gap: 0.4rem; }
.tools-category ul li { font-size: 0.85rem; color: var(--gray-600); }

/* ── STEPS ────────────────────────────────────────── */
.steps-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }

.step-card {
  text-align: center;
  padding: 2rem;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--lime);
  color: var(--black);
  font-size: 1.5rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step-card h3 { font-size: 1.1rem; font-weight: 700; color: var(--black); margin-bottom: 0.5rem; }
.step-card p { font-size: 0.9rem; color: var(--gray-600); }

/* ── RESOURCES CARDS ──────────────────────────────── */
.resource-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}

.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

.resource-card-type {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 0.25rem 0.7rem;
  border-radius: 50px;
  margin-bottom: 0.75rem;
}

.resource-card h3 { font-size: 1rem; font-weight: 700; color: var(--black); margin-bottom: 0.5rem; }
.resource-card p { font-size: 0.88rem; color: var(--gray-600); }
.resource-card-link {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-top: 1rem;
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--black);
  text-decoration: none;
}
.resource-card-link:hover { color: var(--burgundy); }

/* ── FILE TYPES ───────────────────────────────────── */
.file-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

.file-type-chip {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 50px;
  padding: 0.6rem 1.25rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-700);
  transition: border-color var(--transition), background var(--transition);
}

.file-type-chip:hover { border-color: var(--black); background: var(--gray-50); }

/* ── SPOTLIGHT CARDS ──────────────────────────────── */
.spotlight-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}

.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

.spotlight-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: var(--black);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.spotlight-card h3 { font-size: 1.05rem; font-weight: 700; color: var(--black); margin-bottom: 0.4rem; }
.spotlight-card p { font-size: 0.88rem; color: var(--gray-600); }

/* ── SOCIAL PROOF BANNER ─────────────────────────── */
.social-proof-banner {
  background: var(--lime);
  padding: 3rem 2rem;
  text-align: center;
}

.social-proof-banner h2 {
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 800;
  color: var(--black);
  margin-bottom: 0.5rem;
}

.social-proof-banner p { font-size: 1rem; color: rgba(0,0,0,0.7); }

/* ── GLOBAL SCALE ─────────────────────────────────── */
.global-visual {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  border: 2px dashed var(--gray-200);
  position: relative;
  overflow: hidden;
}

.globe-dots {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  grid-template-rows: repeat(10, 1fr);
  gap: 2px;
  padding: 2rem;
  opacity: 0.4;
}

.globe-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--black);
}

.globe-dot.lit { background: var(--lime); opacity: 1; }

.global-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 2rem; }

.global-stat-card {
  background: var(--black);
  border-radius: var(--radius);
  padding: 1.5rem;
  text-align: center;
}

.global-stat-card .stat-num { font-size: 2rem; }

/* ── PRODUCT DEMO ACCORDION ──────────────────────── */
.demo-accordion { border: 2px solid var(--gray-200); border-radius: var(--radius-lg); overflow: hidden; }
.demo-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 2rem;
  cursor: pointer;
  font-weight: 700;
  font-size: 1rem;
  color: var(--black);
  background: var(--gray-50);
  border: none;
  width: 100%;
  font-family: inherit;
  text-align: left;
  transition: background var(--transition);
}

.demo-accordion-header:hover { background: var(--gray-100); }

.demo-toggle-icon {
  font-size: 1.5rem;
  line-height: 1;
  transition: transform 0.3s;
}

.demo-accordion.open .demo-toggle-icon { transform: rotate(45deg); }

.demo-accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.demo-accordion.open .demo-accordion-body { max-height: 600px; }

.demo-body-inner { padding: 2rem; }

/* ── RESPONSIVE ───────────────────────────────────── */
@media (max-width: 1024px) {
  .grid-4, .products-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-mobile-btn { display: block; }
  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 68px; left: 0; right: 0;
    background: var(--white);
    border-bottom: 1px solid var(--gray-200);
    padding: 1rem;
    z-index: 99;
  }
  .grid-3, .steps-grid, .why-tab-panel.active { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .stats-bar-inner { gap: 1.5rem; }
  .stat-divider { display: none; }
  .products-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .pricing-card.featured { transform: scale(1); }
  .testimonial-card { min-width: 280px; }
}

@media (max-width: 480px) {
  .section { padding: 3rem 1.25rem; }
  .hero { padding: 3rem 1.25rem 2.5rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
}

/* ── ANIMATIONS ──────────────────────────────────── */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in { animation: fadeInUp 0.6s ease both; }

.why-tab-panel.active { animation: fadeInUp 0.3s ease both; }

/* LearnForge — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #ffffff;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --radius: 12px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.12);
  --transition: 0.25s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-800);
  background: var(--white);
}

/* ── NAV ─────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 0 2rem;
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 68px;
  gap: 2rem;
}

.nav-logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--black);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}

.nav-logo span {
  display: inline-block;
  width: 28px;
  height: 28px;
  background: var(--lime);
  border-radius: 6px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  list-style: none;
  flex: 1;
}

.nav-links a {
  display: block;
  padding: 0.5rem 0.85rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-700);
  text-decoration: none;
  border-radius: 8px;
  transition: background var(--transition), color var(--transition);
}

.nav-links a:hover,
.nav-links a.active { background: var(--gray-100); color: var(--black); }

.nav-cta {
  display: inline-flex;
  align-items: center;
  padding: 0.6rem 1.4rem;
  background: var(--black);
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
  text-decoration: none;
  border-radius: 50px;
  white-space: nowrap;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}

.nav-cta:hover { background: var(--burgundy); transform: translateY(-1px); }

.nav-mobile-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  color: var(--gray-700);
}

/* ── HERO ─────────────────────────────────────────── */
.hero {
  padding: 5rem 2rem 4rem;
  text-align: center;
  background: linear-gradient(160deg, #fafafa 0%, #f5f5f5 100%);
  overflow: hidden;
}

.hero-inner { max-width: 900px; margin: 0 auto; }

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.1;
  color: var(--black);
  margin-bottom: 1.25rem;
  letter-spacing: -0.02em;
}

.hero h1 .accent { color: var(--burgundy); }

.hero p {
  font-size: 1.15rem;
  color: var(--gray-600);
  max-width: 640px;
  margin: 0 auto 2rem;
}

.hero-btns {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 3rem;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  padding: 0.85rem 2rem;
  background: var(--black);
  color: var(--white);
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  border-radius: 50px;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary:hover { background: var(--burgundy); transform: translateY(-2px); }

.btn-secondary {
  display: inline-flex;
  align-items: center;
  padding: 0.85rem 2rem;
  background: transparent;
  color: var(--black);
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  border-radius: 50px;
  border: 2px solid var(--black);
  transition: background var(--transition), color var(--transition), transform var(--transition);
}

.btn-secondary:hover { background: var(--black); color: var(--white); transform: translateY(-2px); }

/* Hero Tabs */
.hero-tabs {
  display: inline-flex;
  background: var(--white);
  border-radius: 50px;
  padding: 4px;
  box-shadow: var(--shadow);
  margin-bottom: 1.5rem;
}

.hero-tab-btn {
  padding: 0.5rem 1.5rem;
  border: none;
  background: none;
  border-radius: 50px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  color: var(--gray-600);
  transition: background var(--transition), color var(--transition);
}

.hero-tab-btn.active { background: var(--black); color: var(--white); }

.hero-preview {
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  max-width: 820px;
  margin: 0 auto;
  border: 1px solid var(--gray-200);
}

.hero-preview-panel {
  display: none;
  background: var(--white);
  padding: 2rem;
}

.hero-preview-panel.active { display: block; }

.preview-mockup {
  background: var(--gray-50);
  border-radius: var(--radius);
  padding: 1.5rem 2rem;
  text-align: left;
}

.preview-mockup-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.mockup-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--gray-200);
}

.mockup-dot:first-child { background: #ff5f57; }
.mockup-dot:nth-child(2) { background: #febc2e; }
.mockup-dot:nth-child(3) { background: #28c840; }

.preview-mockup-url {
  flex: 1;
  background: var(--white);
  border-radius: 6px;
  padding: 0.3rem 0.75rem;
  font-size: 0.8rem;
  color: var(--gray-400);
  border: 1px solid var(--gray-200);
}

.preview-grid {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 1rem;
  min-height: 220px;
}

.preview-sidebar {
  background: var(--black);
  border-radius: var(--radius);
  padding: 1rem;
  color: var(--white);
}

.preview-sidebar-item {
  padding: 0.5rem 0.75rem;
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
}

.preview-sidebar-item.active { background: var(--lime); color: var(--black); }

.preview-main-content {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.preview-stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.preview-stat-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1rem;
  border: 1px solid var(--gray-200);
  text-align: center;
}

.preview-stat-card .stat-num {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--black);
}

.preview-stat-card .stat-label {
  font-size: 0.7rem;
  color: var(--gray-600);
}

.preview-chart {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1rem;
  border: 1px solid var(--gray-200);
  height: 100px;
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
}

.bar-chart-bar {
  flex: 1;
  border-radius: 4px 4px 0 0;
  background: var(--lime);
  opacity: 0.8;
}

.preview-course-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1rem;
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.course-thumb {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  background: var(--lime);
  flex-shrink: 0;
}

.course-info { flex: 1; }
.course-title { font-size: 0.85rem; font-weight: 700; color: var(--black); }
.course-meta { font-size: 0.75rem; color: var(--gray-600); }

.progress-bar-wrap {
  background: var(--gray-200);
  border-radius: 4px;
  height: 6px;
  margin-top: 0.4rem;
}

.progress-bar-fill {
  height: 100%;
  border-radius: 4px;
  background: var(--lime);
}

/* ── STATS BAR ────────────────────────────────────── */
.stats-bar {
  background: var(--black);
  padding: 2.5rem 2rem;
}

.stats-bar-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3rem;
  flex-wrap: wrap;
}

.stat-item { text-align: center; }

.stat-num {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--lime);
  line-height: 1;
  display: block;
}

.stat-label {
  font-size: 0.9rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.25rem;
}

.stat-divider {
  width: 1px;
  height: 50px;
  background: rgba(255,255,255,0.15);
}

/* ── SECTION COMMONS ─────────────────────────────── */
.section { padding: 5rem 2rem; }
.section-alt { background: var(--gray-50); }

.section-inner { max-width: 1200px; margin: 0 auto; }

.section-label {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 0.3rem 0.9rem;
  border-radius: 50px;
  margin-bottom: 1rem;
}

.section-title {
  font-size: clamp(1.8rem, 3.5vw, 2.75rem);
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.05rem;
  color: var(--gray-600);
  max-width: 600px;
}

.section-header { margin-bottom: 3rem; }
.section-header.centered { text-align: center; }
.section-header.centered .section-subtitle { margin: 0 auto; }

/* ── CARDS ────────────────────────────────────────── */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-200);
  transition: transform var(--transition), box-shadow var(--transition);
}

.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

.card-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.4rem;
}

.card h3 { font-size: 1.15rem; font-weight: 700; color: var(--black); margin-bottom: 0.5rem; }
.card p { font-size: 0.92rem; color: var(--gray-600); }

/* 3-col grid */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1.5rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.5rem; }

/* ── PRODUCTS SECTION ────────────────────────────── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.product-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem 1.5rem;
  border: 2px solid var(--gray-200);
  text-decoration: none;
  color: inherit;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  border-color: var(--black);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-card-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.product-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--black);
  margin-bottom: 0.5rem;
}

.product-card p {
  font-size: 0.88rem;
  color: var(--gray-600);
  flex: 1;
}

.product-card-link {
  margin-top: 1.25rem;
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--burgundy);
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

/* ── WHY CHOOSE US TABS ───────────────────────────── */
.why-tabs {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
  border-bottom: 2px solid var(--gray-200);
  padding-bottom: 0;
}

.why-tab-btn {
  padding: 0.75rem 1.25rem;
  border: none;
  background: none;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  color: var(--gray-600);
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  transition: color var(--transition), border-color var(--transition);
}

.why-tab-btn:hover { color: var(--black); }
.why-tab-btn.active { color: var(--black); border-bottom-color: var(--lime); }

.why-tab-panel { display: none; }
.why-tab-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 2.5rem; align-items: center; }

.why-features-list { list-style: none; display: flex; flex-direction: column; gap: 0.75rem; }

.why-features-list li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.95rem;
  color: var(--gray-700);
}

.why-features-list li::before {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--lime);
  flex-shrink: 0;
}

.why-visual {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  height: 280px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  border: 2px dashed var(--gray-200);
}

/* ── TESTIMONIALS CAROUSEL ────────────────────────── */
.carousel-wrap { position: relative; overflow: hidden; }

.carousel-track {
  display: flex;
  transition: transform 0.4s ease;
}

.testimonial-card {
  min-width: 380px;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-200);
  margin-right: 1.5rem;
  flex-shrink: 0;
}

.testimonial-tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  background: var(--lime);
  color: var(--black);
  padding: 0.2rem 0.7rem;
  border-radius: 50px;
  margin-bottom: 1rem;
}

.testimonial-quote {
  font-size: 1rem;
  color: var(--gray-700);
  font-style: italic;
  margin-bottom: 1.25rem;
  line-height: 1.65;
}

.testimonial-author { font-weight: 700; font-size: 0.9rem; color: var(--black); }
.testimonial-role { font-size: 0.82rem; color: var(--gray-400); }

.carousel-controls {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  background: var(--white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  transition: background var(--transition), border-color var(--transition), color var(--transition);
}

.carousel-btn:hover { background: var(--black); border-color: var(--black); color: var(--white); }

.carousel-dots { display: flex; gap: 0.4rem; }
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-200);
  cursor: pointer;
  transition: background var(--transition);
}
.carousel-dot.active { background: var(--black); }

/* ── PRICING ──────────────────────────────────────── */
.pricing-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 2px solid var(--gray-200);
  transition: border-color var(--transition), transform var(--transition);
}

.pricing-card.featured {
  border-color: var(--black);
  background: var(--black);
  color: var(--white);
  transform: scale(1.03);
}

.pricing-card:hover:not(.featured) { border-color: var(--black); transform: scale(1.02); }

.pricing-label {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1rem;
  color: var(--gray-600);
}

.pricing-card.featured .pricing-label { color: var(--lime); }

.pricing-price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--black);
  margin-bottom: 0.25rem;
}

.pricing-card.featured .pricing-price { color: var(--white); }
.pricing-card.featured .pricing-note { color: rgba(255,255,255,0.6); }
.pricing-note { font-size: 0.85rem; color: var(--gray-600); margin-bottom: 1.5rem; }

.pricing-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin-bottom: 1.75rem;
}

.pricing-features li {
  font-size: 0.88rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.pricing-features li::before {
  content: '✓';
  font-weight: 700;
  color: var(--lime);
  flex-shrink: 0;
}

.pricing-card.featured .pricing-features li { color: rgba(255,255,255,0.85); }

.pricing-cta {
  display: block;
  text-align: center;
  padding: 0.85rem;
  border-radius: 50px;
  font-weight: 700;
  font-size: 0.9rem;
  text-decoration: none;
  transition: background var(--transition), color var(--transition), transform var(--transition);
}

.pricing-card:not(.featured) .pricing-cta {
  background: var(--lime);
  color: var(--black);
}

.pricing-card:not(.featured) .pricing-cta:hover { background: var(--black); color: var(--white); transform: translateY(-1px); }

.pricing-card.featured .pricing-cta {
  background: var(--lime);
  color: var(--black);
}

.pricing-card.featured .pricing-cta:hover { background: var(--white); }

/* ── INTEGRATIONS ─────────────────────────────────── */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 1rem;
}

.integration-item {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1.25rem 1rem;
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: border-color var(--transition), transform var(--transition);
}

.integration-item:hover { border-color: var(--black); transform: translateY(-2px); }

.integration-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: var(--gray-100);
  margin: 0 auto 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
}

.integration-name { font-size: 0.78rem; font-weight: 600; color: var(--gray-700); }

/* ── FAQ ACCORDION ────────────────────────────────── */
.faq-list { display: flex; flex-direction: column; gap: 0.75rem; max-width: 760px; margin: 0 auto; }

.faq-item {
  background: var(--white);
  border-radius: var(--radius);
  border: 1px solid var(--gray-200);
  overflow: hidden;
  transition: border-color var(--transition);
}

.faq-item.open { border-color: var(--black); }

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  background: none;
  border: none;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--black);
  cursor: pointer;
  text-align: left;
  gap: 1rem;
}

.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  flex-shrink: 0;
  transition: background var(--transition), transform var(--transition);
}

.faq-item.open .faq-icon { background: var(--lime); transform: rotate(45deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
  padding: 0 1.5rem;
}

.faq-item.open .faq-answer { max-height: 300px; padding: 0 1.5rem 1.25rem; }

.faq-answer p { font-size: 0.92rem; color: var(--gray-600); }

/* ── CTA BANNER ───────────────────────────────────── */
.cta-banner {
  background: var(--black);
  padding: 5rem 2rem;
  text-align: center;
}

.cta-banner h2 {
  font-size: clamp(1.8rem, 3.5vw, 2.75rem);
  font-weight: 800;
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-banner p { font-size: 1.05rem; color: rgba(255,255,255,0.7); margin-bottom: 2rem; }

.cta-banner .btn-primary {
  background: var(--lime);
  color: var(--black);
  font-size: 1.05rem;
  padding: 1rem 2.5rem;
}

.cta-banner .btn-primary:hover { background: var(--white); }

/* ── FOOTER ───────────────────────────────────────── */
.footer {
  background: var(--gray-800);
  color: rgba(255,255,255,0.7);
  padding: 4rem 2rem 2rem;
}

.footer-inner { max-width: 1200px; margin: 0 auto; }

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand { }
.footer-logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--white);
  display: flex;
  align-items: center;
  gap: 0.4rem;
  text-decoration: none;
  margin-bottom: 0.75rem;
}

.footer-logo span {
  display: inline-block;
  width: 24px;
  height: 24px;
  background: var(--lime);
  border-radius: 5px;
}

.footer-tagline { font-size: 0.88rem; }

.footer-col h4 {
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--white);
  margin-bottom: 1rem;
}

.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.5rem; }

.footer-col ul a {
  font-size: 0.88rem;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-col ul a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p { font-size: 0.82rem; }

/* ── TOOLS GRID ───────────────────────────────────── */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1.25rem;
}

.tools-category {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1.5rem;
  border: 1px solid var(--gray-200);
}

.tools-category h4 {
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--burgundy);
  margin-bottom: 0.75rem;
}

.tools-category ul { list-style: none; display: flex; flex-direction: column; gap: 0.4rem; }
.tools-category ul li { font-size: 0.85rem; color: var(--gray-600); }

/* ── STEPS ────────────────────────────────────────── */
.steps-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }

.step-card {
  text-align: center;
  padding: 2rem;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--lime);
  color: var(--black);
  font-size: 1.5rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step-card h3 { font-size: 1.1rem; font-weight: 700; color: var(--black); margin-bottom: 0.5rem; }
.step-card p { font-size: 0.9rem; color: var(--gray-600); }

/* ── RESOURCES CARDS ──────────────────────────────── */
.resource-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}

.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

.resource-card-type {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 0.25rem 0.7rem;
  border-radius: 50px;
  margin-bottom: 0.75rem;
}

.resource-card h3 { font-size: 1rem; font-weight: 700; color: var(--black); margin-bottom: 0.5rem; }
.resource-card p { font-size: 0.88rem; color: var(--gray-600); }
.resource-card-link {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  margin-top: 1rem;
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--black);
  text-decoration: none;
}
.resource-card-link:hover { color: var(--burgundy); }

/* ── FILE TYPES ───────────────────────────────────── */
.file-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

.file-type-chip {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 50px;
  padding: 0.6rem 1.25rem;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-700);
  transition: border-color var(--transition), background var(--transition);
}

.file-type-chip:hover { border-color: var(--black); background: var(--gray-50); }

/* ── SPOTLIGHT CARDS ──────────────────────────────── */
.spotlight-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2rem;
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}

.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }

.spotlight-icon {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: var(--black);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.spotlight-card h3 { font-size: 1.05rem; font-weight: 700; color: var(--black); margin-bottom: 0.4rem; }
.spotlight-card p { font-size: 0.88rem; color: var(--gray-600); }

/* ── SOCIAL PROOF BANNER ─────────────────────────── */
.social-proof-banner {
  background: var(--lime);
  padding: 3rem 2rem;
  text-align: center;
}

.social-proof-banner h2 {
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 800;
  color: var(--black);
  margin-bottom: 0.5rem;
}

.social-proof-banner p { font-size: 1rem; color: rgba(0,0,0,0.7); }

/* ── GLOBAL SCALE ─────────────────────────────────── */
.global-visual {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  border: 2px dashed var(--gray-200);
  position: relative;
  overflow: hidden;
}

.globe-dots {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  grid-template-rows: repeat(10, 1fr);
  gap: 2px;
  padding: 2rem;
  opacity: 0.4;
}

.globe-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--black);
}

.globe-dot.lit { background: var(--lime); opacity: 1; }

.global-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-top: 2rem; }

.global-stat-card {
  background: var(--black);
  border-radius: var(--radius);
  padding: 1.5rem;
  text-align: center;
}

.global-stat-card .stat-num { font-size: 2rem; }

/* ── PRODUCT DEMO ACCORDION ──────────────────────── */
.demo-accordion { border: 2px solid var(--gray-200); border-radius: var(--radius-lg); overflow: hidden; }
.demo-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem 2rem;
  cursor: pointer;
  font-weight: 700;
  font-size: 1rem;
  color: var(--black);
  background: var(--gray-50);
  border: none;
  width: 100%;
  font-family: inherit;
  text-align: left;
  transition: background var(--transition);
}

.demo-accordion-header:hover { background: var(--gray-100); }

.demo-toggle-icon {
  font-size: 1.5rem;
  line-height: 1;
  transition: transform 0.3s;
}

.demo-accordion.open .demo-toggle-icon { transform: rotate(45deg); }

.demo-accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.demo-accordion.open .demo-accordion-body { max-height: 600px; }

.demo-body-inner { padding: 2rem; }

/* ── RESPONSIVE ───────────────────────────────────── */
@media (max-width: 1024px) {
  .grid-4, .products-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-mobile-btn { display: block; }
  .nav-links.mobile-open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 68px; left: 0; right: 0;
    background: var(--white);
    border-bottom: 1px solid var(--gray-200);
    padding: 1rem;
    z-index: 99;
  }
  .grid-3, .steps-grid, .why-tab-panel.active { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .stats-bar-inner { gap: 1.5rem; }
  .stat-divider { display: none; }
  .products-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .pricing-card.featured { transform: scale(1); }
  .testimonial-card { min-width: 280px; }
}

@media (max-width: 480px) {
  .section { padding: 3rem 1.25rem; }
  .hero { padding: 3rem 1.25rem 2.5rem; }
  .footer-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr; }
}

/* ── ANIMATIONS ──────────────────────────────────── */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.animate-in { animation: fadeInUp 0.6s ease both; }

.why-tab-panel.active { animation: fadeInUp 0.3s ease both; }

